export const DEFAULT_MAX_LINES = 2000;
export const DEFAULT_MAX_BYTES = 50 * 1024; // 50KB
export const GREP_MAX_LINE_LENGTH = 500; // Max chars per grep match line

/** Result metadata for content truncated by line count, byte count, or both. */
export interface TruncationResult {
  /** The truncated content */
  content: string;
  /** Whether truncation occurred */
  truncated: boolean;
  /** Which limit was hit: "lines", "bytes", or null if not truncated */
  truncatedBy: "lines" | "bytes" | null;
  /** Total number of lines in the original content */
  totalLines: number;
  /** Total number of bytes in the original content */
  totalBytes: number;
  /** Number of complete lines in the truncated output */
  outputLines: number;
  /** Number of bytes in the truncated output */
  outputBytes: number;
  /** Whether the last line was partially truncated (only for tail truncation edge case) */
  lastLinePartial: boolean;
  /** Whether the first line exceeded the byte limit (for head truncation) */
  firstLineExceedsLimit: boolean;
  /** The max lines limit that was applied */
  maxLines: number;
  /** The max bytes limit that was applied */
  maxBytes: number;
}

/** Byte and line ceilings used by the truncation helpers. */
export interface TruncationOptions {
  /** Maximum number of lines (default: 2000) */
  maxLines?: number;
  /** Maximum number of bytes (default: 50KB) */
  maxBytes?: number;
}

type ResolvedTruncationInput = ReturnType<typeof resolveTruncationInput>;

interface RuntimeBuffer {
  byteLength(content: string, encoding: "utf8"): number;
  from(content: string, encoding: "utf16le"): { toString(encoding: "utf16le"): string };
}

const runtimeBuffer = (globalThis as { Buffer?: RuntimeBuffer }).Buffer;

function copyString(content: string): string {
  // Copy selected code units without normalizing lone surrogates or retaining the source backing.
  return runtimeBuffer ? runtimeBuffer.from(content, "utf16le").toString("utf16le") : content;
}

function findFirstNonAscii(content: string): number {
  for (let index = 0; index < content.length; index++) {
    if (content.charCodeAt(index) > 0x7f) {
      return index;
    }
  }
  return -1;
}

function utf8ByteLength(content: string): number {
  if (runtimeBuffer) {
    return runtimeBuffer.byteLength(content, "utf8");
  }

  const firstNonAscii = findFirstNonAscii(content);
  if (firstNonAscii === -1) {
    return content.length;
  }

  let bytes = firstNonAscii;
  for (let i = firstNonAscii; i < content.length; i++) {
    const code = content.charCodeAt(i);
    if (code <= 0x7f) {
      bytes += 1;
    } else if (code <= 0x7ff) {
      bytes += 2;
    } else if (code >= 0xd800 && code <= 0xdbff && i + 1 < content.length) {
      const next = content.charCodeAt(i + 1);
      if (next >= 0xdc00 && next <= 0xdfff) {
        bytes += 4;
        i++;
      } else {
        bytes += 3;
      }
    } else {
      bytes += 3;
    }
  }
  return bytes;
}

/**
 * Format byte counts for compact tool-output diagnostics.
 */
export function formatSize(bytes: number): string {
  if (bytes < 1024) {
    return `${bytes}B`;
  } else if (bytes < 1024 * 1024) {
    return `${(bytes / 1024).toFixed(1)}KB`;
  }
  return `${(bytes / (1024 * 1024)).toFixed(1)}MB`;
}

function resolveTruncationInput(content: string, options: TruncationOptions) {
  let totalLines = content.length > 0 && !content.endsWith("\n") ? 1 : 0;
  for (let index = content.indexOf("\n"); index !== -1; index = content.indexOf("\n", index + 1)) {
    totalLines++;
  }
  return {
    totalLines,
    totalBytes: utf8ByteLength(content),
    maxLines: options.maxLines ?? DEFAULT_MAX_LINES,
    maxBytes: options.maxBytes ?? DEFAULT_MAX_BYTES,
  };
}

function buildTruncationResult(
  input: ResolvedTruncationInput,
  params: {
    content: string;
    truncatedBy?: TruncationResult["truncatedBy"];
    outputLines?: number;
    outputBytes?: number;
    lastLinePartial?: boolean;
    firstLineExceedsLimit?: boolean;
  },
): TruncationResult {
  let truncatedBy = params.truncatedBy ?? null;
  const outputLines = params.outputLines ?? input.totalLines;
  const outputBytes = params.outputBytes ?? input.totalBytes;
  if (
    !params.firstLineExceedsLimit &&
    input.totalLines > input.maxLines &&
    outputLines >= input.maxLines &&
    outputBytes <= input.maxBytes
  ) {
    truncatedBy = "lines";
  }
  const truncated = truncatedBy !== null;
  return {
    // One-element joins can retain a source slice; multiline joins build their own text.
    content: truncated && outputLines === 1 ? copyString(params.content) : params.content,
    truncated,
    truncatedBy,
    totalLines: input.totalLines,
    totalBytes: input.totalBytes,
    outputLines,
    outputBytes,
    lastLinePartial: params.lastLinePartial ?? false,
    firstLineExceedsLimit: params.firstLineExceedsLimit ?? false,
    maxLines: input.maxLines,
    maxBytes: input.maxBytes,
  };
}

/**
 * Keep the beginning of content while respecting independent line and byte ceilings.
 *
 * Head truncation preserves complete lines; a first line that exceeds the byte
 * ceiling produces empty output and sets firstLineExceedsLimit.
 */
export function truncateHead(content: string, options: TruncationOptions = {}): TruncationResult {
  const input = resolveTruncationInput(content, options);

  if (input.totalLines <= input.maxLines && input.totalBytes <= input.maxBytes) {
    return buildTruncationResult(input, { content });
  }

  const firstLineEnd = content.indexOf("\n");
  const firstLine = content.slice(0, firstLineEnd === -1 ? content.length : firstLineEnd);
  if (input.totalLines > 0 && utf8ByteLength(firstLine) > input.maxBytes) {
    return buildTruncationResult(input, {
      content: "",
      truncatedBy: "bytes",
      outputLines: 0,
      outputBytes: 0,
      firstLineExceedsLimit: true,
    });
  }

  const outputLines: string[] = [];
  let outputBytesCount = 0;
  let truncatedBy: "lines" | "bytes" = input.totalLines > input.maxLines ? "lines" : "bytes";
  // Preserve slice(0, maxLines) semantics for negative and fractional ceilings.
  const lineLimit = Math.trunc(input.maxLines) || 0;
  const selectedLines = Math.min(
    input.totalLines,
    lineLimit < 0 ? input.totalLines + lineLimit : lineLimit,
  );
  for (let start = 0; outputLines.length < selectedLines;) {
    const newline = content.indexOf("\n", start);
    const end = newline === -1 ? content.length : newline;
    const line = content.slice(start, end);
    const lineBytes = utf8ByteLength(line) + (outputLines.length > 0 ? 1 : 0);

    if (outputBytesCount + lineBytes > input.maxBytes) {
      truncatedBy = "bytes";
      break;
    }

    outputLines.push(line);
    start = end + 1;
    outputBytesCount += lineBytes;
  }

  return buildTruncationResult(input, {
    content: outputLines.join("\n"),
    truncatedBy,
    outputLines: outputLines.length,
    outputBytes: outputBytesCount,
  });
}

/**
 * Keep the end of content while respecting independent line and byte ceilings.
 *
 * Tail truncation preserves recent output for command errors and may keep a
 * partial first line when one final line alone exceeds the byte ceiling.
 */
export function truncateTail(content: string, options: TruncationOptions = {}): TruncationResult {
  const input = resolveTruncationInput(content, options);

  if (input.totalLines <= input.maxLines && input.totalBytes <= input.maxBytes) {
    return buildTruncationResult(input, { content });
  }

  const outputLines: string[] = [];
  let outputBytesCount = 0;
  let truncatedBy: "lines" | "bytes" = input.totalLines > input.maxLines ? "lines" : "bytes";
  let lastLinePartial = false;
  // A final newline terminates the last display line; truncated output omits it.
  let end = content.length - (content.endsWith("\n") ? 1 : 0);

  while (outputLines.length < input.totalLines && outputLines.length < input.maxLines) {
    const start = end > 0 ? content.lastIndexOf("\n", end - 1) + 1 : 0;
    const line = content.slice(start, end);
    const lineBytes = utf8ByteLength(line) + (outputLines.length > 0 ? 1 : 0); // +1 for newline

    if (outputBytesCount + lineBytes > input.maxBytes) {
      truncatedBy = "bytes";
      if (outputLines.length === 0) {
        const partialLine = truncateStringToBytesFromEnd(line, input.maxBytes);
        outputLines.push(partialLine);
        outputBytesCount = utf8ByteLength(partialLine);
        lastLinePartial = true;
      }
      break;
    }

    outputLines.push(line);
    end = start - 1;
    outputBytesCount += lineBytes;
  }

  return buildTruncationResult(input, {
    // Join only selected lines so a multiline result does not retain the full source.
    content: outputLines.toReversed().join("\n"),
    truncatedBy,
    outputLines: outputLines.length,
    outputBytes: outputBytesCount,
    lastLinePartial,
  });
}

/**
 * Truncate a string to fit within a byte limit (from the end).
 * Handles multi-byte UTF-8 characters correctly.
 */
function truncateStringToBytesFromEnd(str: string, maxBytes: number): string {
  if (maxBytes <= 0) {
    return "";
  }

  let outputBytes = 0;
  let start = str.length;
  let unchangedEnd = str.length;
  let repairedTail = "";
  for (let i = str.length; i > 0;) {
    let characterStart = i - 1;
    const code = str.charCodeAt(characterStart);
    let characterBytes: number;
    let unpairedSurrogate = false;
    if (code >= 0xdc00 && code <= 0xdfff && characterStart > 0) {
      const previous = str.charCodeAt(characterStart - 1);
      if (previous >= 0xd800 && previous <= 0xdbff) {
        characterStart--;
        characterBytes = 4;
      } else {
        characterBytes = 3;
        unpairedSurrogate = true;
      }
    } else if (code >= 0xd800 && code <= 0xdfff) {
      characterBytes = 3;
      unpairedSurrogate = true;
    } else {
      characterBytes = code <= 0x7f ? 1 : code <= 0x7ff ? 2 : 3;
    }
    if (outputBytes + characterBytes > maxBytes) {
      break;
    }
    outputBytes += characterBytes;
    start = characterStart;
    if (unpairedSurrogate) {
      // Selection already identified the lone surrogate; retain the valid span to its right.
      repairedTail = "\uFFFD" + str.slice(i, unchangedEnd) + repairedTail;
      unchangedEnd = characterStart;
    }
    i = characterStart;
  }

  return str.slice(start, unchangedEnd) + repairedTail;
}

/**
 * Trim a single display line and mark it with the grep-style truncation suffix.
 *
 * The cut point is backed off by one code unit when it would otherwise split a
 * surrogate pair, so emoji / CJK Extension B characters crossing the boundary
 * stay intact instead of rendering as replacement characters.
 */
export function truncateLine(
  line: string,
  maxChars: number = GREP_MAX_LINE_LENGTH,
): { text: string; wasTruncated: boolean } {
  if (line.length <= maxChars) {
    return { text: line, wasTruncated: false };
  }
  let cut = maxChars;
  // Avoid splitting a surrogate pair at the truncation boundary.
  if (cut < line.length) {
    const lastCode = line.charCodeAt(cut - 1);
    if (lastCode >= 0xd800 && lastCode <= 0xdbff) {
      const nextCode = line.charCodeAt(cut);
      if (nextCode >= 0xdc00 && nextCode <= 0xdfff) {
        cut -= 1;
      }
    }
  }
  return { text: `${copyString(line.slice(0, cut))}... [truncated]`, wasTruncated: true };
}

import type {
  AgentLoopConfig,
  AfterToolOutcomeContext,
  AgentMessage,
  AgentToolResult,
  AgentToolUpdateCallback,
  InternalBeforeToolBatchResult,
  ToolLoopWarning,
  ToolLoopIntervention,
  ToolLoopRecoveryState,
  ToolResultContentSource,
} from "./types.js";

type RepetitionGuardPolicy = (model: AgentLoopConfig["model"]) => boolean;
const repetitionGuardByAgent = new WeakMap<object, RepetitionGuardPolicy>();

/** Host policy only: no plugin-facing option or user setting. */
export function setInternalRepetitionGuard(agent: object, policy: RepetitionGuardPolicy): void {
  repetitionGuardByAgent.set(agent, policy);
}

export function getInternalRepetitionGuard(agent: object): RepetitionGuardPolicy | undefined {
  return repetitionGuardByAgent.get(agent);
}

export type InternalBeforeToolBatchHook = NonNullable<AgentLoopConfig["beforeToolBatch"]>;

const beforeToolBatchByAgent = new WeakMap<object, InternalBeforeToolBatchHook>();

export type InternalToolTurnCompletionHook = NonNullable<AgentLoopConfig["completesToolTurn"]>;

const toolTurnCompletionByAgent = new WeakMap<object, InternalToolTurnCompletionHook>();
const toolTurnInputScopeByHook = new WeakMap<InternalToolTurnCompletionHook, object>();

/** Keep the accepted input identity across same-input Agent.continue() calls. */
export function getInternalToolTurnInputScope(hook: InternalToolTurnCompletionHook): object {
  let scope = toolTurnInputScopeByHook.get(hook);
  if (!scope) {
    scope = {};
    toolTurnInputScopeByHook.set(hook, scope);
  }
  return scope;
}

/** Queueing, cancellation and context-only updates do not commit a new input. */
export function commitInternalToolTurnInput(
  hook: InternalToolTurnCompletionHook | undefined,
): void {
  if (hook) {
    toolTurnInputScopeByHook.set(hook, {});
  }
}

type InternalReadyToolCall = { toolCallId: string; args: unknown };

export type InternalToolBatchLifecycle = {
  /**
   * Commit admitted calls in assistant order as they launch: prepared calls just
   * before their implementations start, argument-validation rejections when the
   * launch reaches them. May throw before launch.
   */
  commitReadyCalls?: (calls: readonly InternalReadyToolCall[]) => void;
  /** Release admission state for admitted calls, prepared or rejected, that will not launch. */
  releaseSkippedCalls?: (toolCallIds: readonly string[]) => void;
  /** Observe settled outcomes in assistant order, before warning text changes their identity. */
  observeOutcome?: (
    outcome: Pick<AfterToolOutcomeContext, "toolCall" | "args" | "result" | "isError">,
    state: ToolLoopRecoveryState,
  ) => ToolLoopIntervention | undefined;
};

const toolBatchLifecycleByResult = new WeakMap<
  InternalBeforeToolBatchResult,
  InternalToolBatchLifecycle
>();

type InternalSteeringGetter = NonNullable<AgentLoopConfig["getSteeringMessages"]>;
type InternalSyncSteeringGetter = () => AgentMessage[];
const syncSteeringGetterByCallback = new WeakMap<
  InternalSteeringGetter,
  InternalSyncSteeringGetter
>();

export type InternalSteeringQueueObserver = {
  peek: () => readonly AgentMessage[];
  drainContext?: () => AgentMessage[];
  reserve: (messages: readonly AgentMessage[]) => () => void;
  onChange?: () => void;
  subscribe?: (listener: () => void) => () => void;
};
const steeringQueueObserverByCallback = new WeakMap<
  InternalSteeringGetter,
  InternalSteeringQueueObserver
>();

export type InternalToolExecutionPreparation =
  | {
      kind: "immediate";
      outcome:
        | { kind: "result"; result: AgentToolResult<unknown>; isError: boolean }
        | { kind: "error"; error: unknown };
      dispose: () => void;
    }
  | {
      kind: "ready";
      args: unknown;
      execute: (onImplementationStart?: () => void) => Promise<AgentToolResult<unknown>>;
      dispose: () => void;
    };

export type InternalToolExecutionPreparer = (params: {
  toolCallId: string;
  args: unknown;
  signal?: AbortSignal;
  onUpdate?: AgentToolUpdateCallback;
  executionArgs?: unknown[];
}) => Promise<InternalToolExecutionPreparation>;

const toolExecutionPreparerByTool = new WeakMap<object, InternalToolExecutionPreparer>();

type InternalToolResultAcknowledgement = () => void;
const toolResultAcknowledgementByValue = new WeakMap<object, InternalToolResultAcknowledgement>();
const toolResultProvenanceByValue = new WeakMap<object, object>();
const toolResultContentSourceByValue = new WeakMap<object, ToolResultContentSource>();

/** Copy present private state without clearing a target's existing slot. */
function copyInternalSlot<T>(slots: WeakMap<object, T>, source: object, target: object): void {
  const value = slots.get(source);
  if (value) {
    slots.set(target, value);
  }
}

/** Install OpenClaw-owned loop control without adding a plugin-facing Agent option. */
export function setInternalBeforeToolBatch(
  agent: object,
  hook: InternalBeforeToolBatchHook | undefined,
): void {
  if (hook) {
    beforeToolBatchByAgent.set(agent, hook);
  } else {
    beforeToolBatchByAgent.delete(agent);
  }
}

export function getInternalBeforeToolBatch(agent: object): InternalBeforeToolBatchHook | undefined {
  return beforeToolBatchByAgent.get(agent);
}

export function setInternalToolTurnCompletion(
  agent: object,
  hook: InternalToolTurnCompletionHook | undefined,
): void {
  if (hook) {
    toolTurnCompletionByAgent.set(agent, hook);
  } else {
    toolTurnCompletionByAgent.delete(agent);
  }
}

export function getInternalToolTurnCompletion(
  agent: object,
): InternalToolTurnCompletionHook | undefined {
  return toolTurnCompletionByAgent.get(agent);
}

/** Attach scheduler lifecycle ownership without widening the public admission result. */
export function attachInternalToolBatchLifecycle(
  result: InternalBeforeToolBatchResult,
  lifecycle: InternalToolBatchLifecycle,
): InternalBeforeToolBatchResult {
  toolBatchLifecycleByResult.set(result, lifecycle);
  return result;
}

export function takeInternalToolBatchLifecycle(
  result: InternalBeforeToolBatchResult,
): InternalToolBatchLifecycle | undefined {
  const lifecycle = toolBatchLifecycleByResult.get(result);
  toolBatchLifecycleByResult.delete(result);
  return lifecycle;
}

/** Attach Agent-owned synchronous draining to the exact public async callback identity. */
export function attachInternalSyncSteeringGetter(
  callback: InternalSteeringGetter,
  syncGetter: InternalSyncSteeringGetter,
  observer?: InternalSteeringQueueObserver,
): InternalSteeringGetter {
  syncSteeringGetterByCallback.set(callback, syncGetter);
  attachInternalSteeringQueueObserver(callback, observer);
  return callback;
}

/** Wrapping a getter must retain observation of its exact underlying queue. */
export function attachInternalSteeringQueueObserver(
  callback: InternalSteeringGetter,
  observer: InternalSteeringQueueObserver | undefined,
): void {
  if (observer) {
    steeringQueueObserverByCallback.set(callback, observer);
  }
}

export function getInternalSteeringQueueObserver(
  callback: InternalSteeringGetter | undefined,
): InternalSteeringQueueObserver | undefined {
  return callback ? steeringQueueObserverByCallback.get(callback) : undefined;
}

export function getInternalSyncSteeringGetter(
  callback: InternalSteeringGetter,
): InternalSyncSteeringGetter | undefined {
  return syncSteeringGetterByCallback.get(callback);
}

/** Attach OpenClaw-owned two-phase execution without changing the public AgentTool shape. */
export function attachInternalToolExecutionPreparer<T extends object>(
  tool: T,
  preparer: InternalToolExecutionPreparer,
): T {
  toolExecutionPreparerByTool.set(tool, preparer);
  return tool;
}

export function getInternalToolExecutionPreparer(
  tool: object,
): InternalToolExecutionPreparer | undefined {
  return toolExecutionPreparerByTool.get(tool);
}

/** Preserve private execution ownership when an adapter replaces a tool object. */
export function copyInternalToolExecutionPreparer<T extends object>(source: object, target: T): T {
  copyInternalSlot(toolExecutionPreparerByTool, source, target);
  return target;
}

/** Keep a destructive tool-side commit behind the result persistence boundary. */
export function attachInternalToolResultAcknowledgement<T extends object>(
  value: T,
  acknowledge: InternalToolResultAcknowledgement,
): T {
  toolResultAcknowledgementByValue.set(value, acknowledge);
  return value;
}

export function attachInternalToolResultProvenance<T extends object>(
  value: T,
  provenance: object | undefined,
): T {
  if (provenance) {
    toolResultProvenanceByValue.set(value, provenance);
  } else {
    toolResultProvenanceByValue.delete(value);
  }
  return value;
}

export function getInternalToolResultProvenance(value: object): object | undefined {
  return toolResultProvenanceByValue.get(value);
}

/**
 * Mark one result or thrown error as carrying content from a nested call whose
 * tool declares a result content source. Dispatchers such as Tool Search and
 * Code Mode use this because their own static declaration cannot describe each
 * call; finalization combines it with the executed tool's declaration.
 */
export function attachInternalToolResultContentSource<T extends object>(
  value: T,
  source: ToolResultContentSource,
): T {
  toolResultContentSourceByValue.set(value, source);
  return value;
}

export function getInternalToolResultContentSource(
  value: object,
): ToolResultContentSource | undefined {
  return toolResultContentSourceByValue.get(value);
}

/** Carry private commit ownership through result transforms and message construction. */
export function copyInternalToolResultState<T extends object>(source: object, target: T): T {
  copyInternalSlot(toolResultAcknowledgementByValue, source, target);
  copyInternalSlot(toolResultProvenanceByValue, source, target);
  copyInternalSlot(toolResultContentSourceByValue, source, target);
  return target;
}

/**
 * Feedback must not change no-progress hashes: call only after raw outcome
 * recording, or for rejected calls whose validation result admission captured.
 */
export function appendToolLoopWarning<T extends AgentToolResult<unknown>>(
  result: T,
  warning: ToolLoopWarning,
): T {
  return copyInternalToolResultState(result, {
    ...result,
    content: [
      // Match transcript normalization for tools that omit display content.
      ...(result.content ?? []),
      {
        type: "text",
        text: `[System note: Tool-loop warning after ${warning.count} repeated calls. Change your approach or stop if you are not making progress.]`,
      },
    ],
  });
}

/** Commit one tool result after its owning message has attached. */
export function acknowledgeInternalToolResult(value: object): void {
  const acknowledge = toolResultAcknowledgementByValue.get(value);
  if (!acknowledge) {
    return;
  }
  toolResultAcknowledgementByValue.delete(value);
  acknowledge();
}

import { readNonBlankString } from "@openclaw/normalization-core/string-coerce";
import { isPlainObject } from "../utils.js";
import { normalizeToolPolicyName } from "./tool-policy.js";
import type { AnyAgentTool } from "./tools/common.js";

export const CODE_MODE_EXEC_TOOL_NAME = "exec";
export const CODE_MODE_WAIT_TOOL_NAME = "wait";
const CODE_MODE_EXEC_TOOL_KIND = "code_mode_exec";

type CodeModeExecToolInputKind = "javascript";
type CodeModeExecHookMetadata = {
  toolKind: typeof CODE_MODE_EXEC_TOOL_KIND;
  toolInputKind?: CodeModeExecToolInputKind;
};

const codeModeControlTools = new WeakSet<object>();
export function markCodeModeControlTool<T extends AnyAgentTool>(tool: T): T {
  codeModeControlTools.add(tool);
  return tool;
}

export function copyCodeModeControlToolIdentity(original: object, wrapper: object): void {
  if (codeModeControlTools.has(original)) {
    codeModeControlTools.add(wrapper);
  }
}

export function isCodeModeControlTool(tool: object): boolean {
  return codeModeControlTools.has(tool);
}

/** Return whether a tool is the marked Code Mode `exec` control tool (not a plain shell exec). */
export function isCodeModeExecTool(tool: AnyAgentTool): boolean {
  return (
    isCodeModeControlTool(tool) && normalizeToolPolicyName(tool.name) === CODE_MODE_EXEC_TOOL_NAME
  );
}

function resolveCodeModeExecToolInputKind(params: unknown): CodeModeExecToolInputKind | undefined {
  if (!isPlainObject(params)) {
    return undefined;
  }
  return params.language === undefined && params.typecheck === undefined ? "javascript" : undefined;
}

function normalizeCodeModeExecParams(params: unknown): unknown {
  if (!isPlainObject(params)) {
    return params;
  }
  const code = readNonBlankString(params.code);
  const command = readNonBlankString(params.command);
  if (code !== undefined && command === undefined) {
    // Code-mode accepts both `code` and generic exec `command`; keep them paired
    // so downstream hooks can read either shape.
    return { ...params, command: code };
  }
  if (command !== undefined && code === undefined) {
    return { ...params, code: command };
  }
  return params;
}

export function getCodeModeExecBeforeHookMetadata(params: {
  tool: AnyAgentTool;
  params: unknown;
}): CodeModeExecHookMetadata | undefined {
  if (!isCodeModeExecTool(params.tool)) {
    return undefined;
  }
  return getCodeModeExecBeforeHookMetadataForToolKind({
    toolKind: CODE_MODE_EXEC_TOOL_KIND,
    params: params.params,
  });
}

export function getCodeModeExecBeforeHookMetadataForToolKind(params: {
  toolKind: unknown;
  params: unknown;
}): CodeModeExecHookMetadata | undefined {
  if (params.toolKind !== CODE_MODE_EXEC_TOOL_KIND) {
    return undefined;
  }
  const toolInputKind = resolveCodeModeExecToolInputKind(params.params);
  return {
    toolKind: CODE_MODE_EXEC_TOOL_KIND,
    ...(toolInputKind && { toolInputKind }),
  };
}

export function normalizeCodeModeExecBeforeHookParams(params: {
  tool: AnyAgentTool;
  params: unknown;
}): unknown {
  if (!isCodeModeExecTool(params.tool)) {
    return params.params;
  }
  return normalizeCodeModeExecParams(params.params);
}

type CodeModeExecReconcileOwner = { tool: AnyAgentTool } | { toolKind: unknown };

/** Reconcile policy- or hook-adjusted aliases after raw-input normalization. */
export function reconcileCodeModeExecBeforeHookParams(params: {
  owner: CodeModeExecReconcileOwner;
  originalParams: unknown;
  hookParams: unknown;
  adjustedParams: unknown;
}): unknown {
  const isCodeModeExecOwner =
    "tool" in params.owner
      ? isCodeModeExecTool(params.owner.tool)
      : params.owner.toolKind === CODE_MODE_EXEC_TOOL_KIND;
  if (
    !isCodeModeExecOwner ||
    !isPlainObject(params.originalParams) ||
    !isPlainObject(params.hookParams) ||
    !isPlainObject(params.adjustedParams)
  ) {
    return params.adjustedParams;
  }
  const hookCode = params.hookParams.code;
  const hookCommand = params.hookParams.command;
  if (typeof hookCode !== "string" || hookCode !== hookCommand) {
    return params.adjustedParams;
  }

  const adjustedCode = params.adjustedParams.code;
  const adjustedCommand = params.adjustedParams.command;
  const adjustedCodeChanged =
    Object.hasOwn(params.adjustedParams, "code") && adjustedCode !== hookCode;
  const adjustedCommandChanged =
    Object.hasOwn(params.adjustedParams, "command") && adjustedCommand !== hookCode;
  // Invalidation must dominate a simultaneous valid rewrite; otherwise runtime
  // ignores the invalid alias and executes the other one.
  if (adjustedCodeChanged && readNonBlankString(adjustedCode) === undefined) {
    return { ...params.adjustedParams, command: adjustedCode };
  }
  if (adjustedCommandChanged && readNonBlankString(adjustedCommand) === undefined) {
    return { ...params.adjustedParams, code: adjustedCommand };
  }
  if (adjustedCodeChanged === adjustedCommandChanged) {
    return params.adjustedParams;
  }

  if (adjustedCodeChanged) {
    return { ...params.adjustedParams, command: adjustedCode };
  }
  return { ...params.adjustedParams, code: adjustedCommand };
}

/**
 * Provider-safe TypeBox string enum helpers.
 *
 * Emits flat `enum` schemas instead of `anyOf` unions so provider tool-schema validators accept them.
 */
import { Type } from "typebox";

type StringEnumOptions<T extends readonly string[]> = {
  description?: string;
  title?: string;
  default?: T[number];
  deprecated?: boolean;
};

export function stringEnum<T extends readonly string[]>(
  values: T,
  options: StringEnumOptions<T> = {},
) {
  const enumValues = Array.isArray(values)
    ? values
    : values && typeof values === "object"
      ? Object.values(values).filter((value): value is T[number] => typeof value === "string")
      : [];
  return enumValues.length === 0
    ? Type.Unsafe<T[number]>({ type: "string", ...options })
    : Type.Enum(enumValues, { type: "string", ...options });
}

export function optionalStringEnum<T extends readonly string[]>(
  values: T,
  options: StringEnumOptions<T> = {},
) {
  return Type.Optional(stringEnum(values, options));
}

/**
 * Shared TypeBox schema helpers for agent tools.
 *
 * Tool definitions use these helpers for channel targets and common optional
 * numeric fields so provider-facing schemas stay consistent.
 */
import { Type, type TOptional, type TString } from "typebox";
import {
  CHANNEL_TARGET_DESCRIPTION,
  CHANNEL_TARGETS_DESCRIPTION,
} from "../../infra/outbound/channel-target.js";
export { optionalStringEnum, stringEnum } from "./string-enum.js";

export function requesterProfileSchema(options: { defaultToTurnOwner?: boolean } = {}) {
  return Type.Optional(
    Type.String({
      description: options.defaultToTurnOwner
        ? "An admitted participant's requester_profile.id. Omit to use the turn's original requester; selection does not establish human intent or approval."
        : "The person's requester_profile.id, required when several people have steered this turn.",
    }),
  );
}

/** Describe the intended work; completion is reported by the tool result. */
export function executionTitleSchema(options: { required: true }): TString;
export function executionTitleSchema(options?: { required?: false }): TOptional<TString>;
export function executionTitleSchema(options: { required?: boolean } = {}) {
  const schema = Type.String({
    maxLength: 120,
    description: "Every call: short purpose; never claim success. No secrets.",
    ...(options.required ? { minLength: 1, pattern: "\\S" } : {}),
  });
  return options.required ? schema : Type.Optional(schema);
}

/** Builds a schema for one outbound channel target. */
export function channelTargetSchema(options?: { description?: string }) {
  return Type.String({
    description: options?.description ?? CHANNEL_TARGET_DESCRIPTION,
  });
}

/** Builds a schema for multiple outbound channel targets. */
export function channelTargetsSchema(options?: { description?: string }) {
  return Type.Array(
    channelTargetSchema({ description: options?.description ?? CHANNEL_TARGETS_DESCRIPTION }),
  );
}

type IntegerSchemaOptions = {
  description?: string;
  maximum?: number;
};

type NumberSchemaOptions = {
  description?: string;
  deprecated?: boolean;
  minimum?: number;
  maximum?: number;
  exclusiveMinimum?: number;
  exclusiveMaximum?: number;
};

/** Builds an optional finite number schema with caller-provided metadata. */
export function optionalFiniteNumberSchema(options: NumberSchemaOptions = {}) {
  return Type.Optional(Type.Number(options));
}

function optionalIntegerSchema(minimum: number, options: IntegerSchemaOptions) {
  return Type.Optional(Type.Integer({ minimum, ...options }));
}

/** Builds an optional positive integer schema. */
export function optionalPositiveIntegerSchema(options: IntegerSchemaOptions = {}) {
  return optionalIntegerSchema(1, options);
}

/** Builds an optional non-negative integer schema. */
export function optionalNonNegativeIntegerSchema(options: IntegerSchemaOptions = {}) {
  return optionalIntegerSchema(0, options);
}

import { constants } from "node:fs";
import {
  access as fsAccess,
  readFile as fsReadFile,
  writeFile as fsWriteFile,
} from "node:fs/promises";
import { repairJson } from "@openclaw/ai/internal/runtime";
import { isRecord } from "@openclaw/normalization-core/record-coerce";
import { truncateUtf16Safe } from "@openclaw/normalization-core/utf16-slice";
import { hasErrnoCode } from "../../../infra/errno.js";
import {
  captureAgentToolSourceExecutionGuard,
  runWithAgentToolSourceExecutionScope,
} from "../../agent-tool-source-execution-guard.js";
import type { AgentTool } from "../../runtime/index.js";
import { ToolInputError } from "../../tool-input-error.js";
import { textResult } from "../../tools/tool-results.js";
import { decodeUtf8File } from "../../utf8-file.js";
import {
  resolveFileMutationQueueKey,
  withFileMutationQueueKeyResolution,
} from "./file-mutation-queue.js";
import { assertFileToolNotAborted } from "./file-tool-abort.js";
import { planFileEdit } from "./file-tool-planning.js";
import {
  type PersistedFileStat,
  readPersistedFileStat,
  verifyPersistedUtf8File,
} from "./file-write-verification.js";
import { resolveLocalPathToCwd, resolveToCwd } from "./path-utils.js";
import type { EditToolDetails, EditToolInput } from "./tool-contracts.js";
import { wrapToolDefinition } from "./tool-definition-wrapper.js";
import { editSchema, EditToolOutputSchema } from "./tool-schemas.js";

const EDIT_MISMATCH_MESSAGE = "Could not find the exact text in";
const EDIT_MISMATCH_HINT_LIMIT = 800;

/**
 * Pluggable operations for the edit tool.
 * Override these to delegate file editing to remote systems (for example SSH).
 */
interface EditOperations {
  /** Resolve the physical identity used to order this backend's file operations. */
  resolveQueueKey?: (absolutePath: string, signal?: AbortSignal) => string | Promise<string>;
  /** Read file contents as a Buffer */
  readFile: (absolutePath: string) => Promise<Buffer>;
  /** Write content to a file */
  writeFile: (absolutePath: string, content: string) => Promise<void>;
  /** Stat the target before reporting success */
  statFile: (absolutePath: string) => Promise<PersistedFileStat | null>;
  /** Check if file is readable and writable (throw if not) */
  access: (absolutePath: string) => Promise<void>;
}

const defaultEditOperations: EditOperations = {
  readFile: (path) => fsReadFile(path),
  writeFile: (path, content) => fsWriteFile(path, content, "utf-8"),
  statFile: (path) => readPersistedFileStat(path, (error) => hasErrnoCode(error, "ENOENT")),
  access: (path) => fsAccess(path, constants.R_OK | constants.W_OK),
};

export interface EditToolOptions {
  /** Custom operations for file editing. Default: local filesystem */
  operations?: EditOperations;
}

function prepareEditArguments(input: unknown): EditToolInput {
  if (!input || typeof input !== "object") {
    return input as EditToolInput;
  }

  const args = { ...(input as Record<string, unknown>) };

  // Serialized replacements contain literal file text, so valid JSON escapes must
  // survive rather than being reinterpreted by the repair owner's path heuristic.
  if (typeof args.edits === "string") {
    try {
      const parsed = JSON.parse(repairJson(args.edits, { preserveValidControlEscapes: true }));
      if (Array.isArray(parsed)) {
        args.edits = parsed;
      }
    } catch {
      if (typeof args.oldText !== "string" || typeof args.newText !== "string") {
        throw new ToolInputError(
          "Could not parse edits as JSON. Provide a complete JSON array of replacements.",
        );
      }
    }
  }

  let edits = Array.isArray(args.edits)
    ? args.edits.map((edit) => {
        if (!isRecord(edit)) {
          return edit;
        }
        return { oldText: edit.oldText, newText: edit.newText };
      })
    : args.edits;

  const { oldText, newText } = args;
  if (typeof oldText === "string" && typeof newText === "string") {
    const batch = Array.isArray(edits) ? edits : [];
    if (
      !batch.some(
        (edit: unknown) => isRecord(edit) && edit.oldText === oldText && edit.newText === newText,
      )
    ) {
      batch.push({ oldText, newText });
    }
    edits = batch;
  }

  // Keep the strict provider schema while tolerating model-added metadata.
  return { path: args.path, edits } as EditToolInput;
}

function appendMismatchHint(error: Error, currentContent: string): Error {
  const snippet =
    currentContent.length <= EDIT_MISMATCH_HINT_LIMIT
      ? currentContent
      : `${truncateUtf16Safe(currentContent, EDIT_MISMATCH_HINT_LIMIT)}\n... (truncated)`;
  const enhanced = new ToolInputError(`${error.message}\nCurrent file contents:\n${snippet}`);
  enhanced.cause = error;
  enhanced.stack = error.stack;
  return enhanced;
}

export function createEditTool(
  cwd: string,
  options?: EditToolOptions,
): AgentTool<typeof editSchema> {
  const ops = options?.operations ?? defaultEditOperations;
  const resolvePath = options?.operations ? resolveToCwd : resolveLocalPathToCwd;
  return wrapToolDefinition<typeof editSchema, EditToolDetails>({
    name: "edit",
    label: "edit",
    description:
      "Exact single-file replacements. oldText unique/non-overlapping against original. Merge nearby changes; omit large unchanged spans.",
    parameters: editSchema,
    outputSchema: EditToolOutputSchema,
    prepareArguments: prepareEditArguments,
    async execute(_toolCallId, input, signal, _onUpdate, _ctx) {
      const assertCurrent = captureAgentToolSourceExecutionGuard();
      if (!Array.isArray(input.edits) || input.edits.length === 0) {
        throw new ToolInputError(
          "Edit tool input is invalid. edits must contain at least one replacement.",
        );
      }
      const { path, edits: originalEdits } = input;
      const absolutePath = resolvePath(path, cwd);
      const queueKey = resolveFileMutationQueueKey(absolutePath, ops.resolveQueueKey, signal);

      return withFileMutationQueueKeyResolution(queueKey, async () => {
        assertFileToolNotAborted(signal);

        let editCount = 0;
        let expectedContent: string | undefined;

        try {
          await runWithAgentToolSourceExecutionScope(assertCurrent, async () => {
            assertCurrent();
            await ops.access(absolutePath);
          });
        } catch (error: unknown) {
          const errorMessage =
            error instanceof Error && "code" in error
              ? `Error code: ${String(error.code)}`
              : String(error);
          throw new Error(`Could not edit file: ${path}. ${errorMessage}.`, {
            cause: error,
          });
        }

        const buffer = await runWithAgentToolSourceExecutionScope(assertCurrent, async () => {
          assertCurrent();
          return ops.readFile(absolutePath);
        });
        const rawContent = decodeUtf8File(buffer, absolutePath);
        try {
          assertFileToolNotAborted(signal);

          const plan = await planFileEdit(
            { path, content: rawContent, edits: originalEdits },
            signal,
          );
          assertFileToolNotAborted(signal);
          if (!plan.changed) {
            return textResult(plan.message, { changed: false } satisfies EditToolDetails);
          }
          editCount = plan.editCount;
          expectedContent = plan.content;
          await runWithAgentToolSourceExecutionScope(assertCurrent, async () => {
            assertCurrent();
            await ops.writeFile(absolutePath, plan.content);
          });
          assertFileToolNotAborted(signal);
          if (
            !(await runWithAgentToolSourceExecutionScope(assertCurrent, async () => {
              assertCurrent();
              return verifyPersistedUtf8File(absolutePath, plan.content, ops);
            }))
          ) {
            throw new Error(
              `Edit verification failed for ${path}: the persisted regular file does not match the requested content. Inspect the target and retry.`,
            );
          }

          return textResult<EditToolDetails>(
            `Successfully replaced ${editCount} block(s) in ${path}.`,
            { changed: true, ...plan.receipt },
          );
        } catch (error: unknown) {
          const normalizedError = error instanceof Error ? error : new Error(String(error));
          const currentContent = await runWithAgentToolSourceExecutionScope(
            assertCurrent,
            async () => {
              assertCurrent();
              return ops
                .readFile(absolutePath)
                .then((current) => current.toString("utf-8"))
                .catch(() => rawContent);
            },
          );
          const recoveryContent = expectedContent;
          if (
            recoveryContent !== undefined &&
            (await runWithAgentToolSourceExecutionScope(assertCurrent, async () => {
              assertCurrent();
              return verifyPersistedUtf8File(absolutePath, recoveryContent, ops);
            }))
          ) {
            return textResult<EditToolDetails>(
              `Successfully replaced ${editCount} block(s) in ${path}.`,
              { changed: true, diff: "", patch: "" },
            );
          }
          if (normalizedError.message.includes(EDIT_MISMATCH_MESSAGE)) {
            throw appendMismatchHint(normalizedError, currentContent);
          }
          throw normalizedError;
        }
      });
    },
  });
}

import { FILE_HEADERS_ONLY, formatPatch, structuredPatch, type StructuredPatchHunk } from "diff";
import { countNewlines } from "../../line-endings.js";

export type FileDiff = {
  diff: string;
  patch: string;
  firstChangedLine?: number;
};

/** Both receipts describe the same hunks from one diff computation. */
export function prepareFileDiff(
  path: string,
  oldContent: string,
  newContent: string,
  options: { context?: number; maxEditLength?: number } = {},
): FileDiff | undefined {
  const patch = structuredPatch(path, path, oldContent, newContent, undefined, undefined, {
    context: 4,
    ...options,
  });
  if (!patch) {
    return undefined;
  }
  return {
    ...formatDiffString(oldContent, newContent, patch.hunks),
    patch: formatPatch(patch, FILE_HEADERS_ONLY),
  };
}

function formatDiffString(
  oldContent: string,
  newContent: string,
  hunks: StructuredPatchHunk[],
): Pick<FileDiff, "diff" | "firstChangedLine"> {
  const oldLineCount = oldContent.split("\n").length;
  const newLineCount = newContent.split("\n").length;
  const lastNewLine = newContent === "" ? 0 : newLineCount - Number(newContent.endsWith("\n"));
  const maxLineNum = Math.max(oldLineCount, newLineCount);
  const lineNumWidth = String(maxLineNum).length;
  const ellipsis = ` ${"".padStart(lineNumWidth, " ")} ...`;
  const output: string[] = [];
  let firstChangedLine: number | undefined;

  for (const [hunkIndex, hunk] of hunks.entries()) {
    if (hunkIndex > 0 || hunk.newStart > 1) {
      output.push(ellipsis);
    }

    let oldLineNum = hunk.oldStart;
    let newLineNum = hunk.newStart;
    for (const line of hunk.lines) {
      const prefix = line[0];
      if (prefix === "\\") {
        continue;
      }
      if (firstChangedLine === undefined && prefix !== " ") {
        firstChangedLine = newLineNum;
      }
      const lineNum = prefix === "-" ? oldLineNum : newLineNum;
      output.push(`${prefix}${String(lineNum).padStart(lineNumWidth, " ")} ${line.slice(1)}`);
      oldLineNum += prefix === "+" ? 0 : 1;
      newLineNum += prefix === "-" ? 0 : 1;
    }

    if (hunkIndex === hunks.length - 1 && hunk.newStart + hunk.newLines <= lastNewLine) {
      output.push(ellipsis);
    }
  }

  return { diff: output.join("\n"), firstChangedLine };
}

export const WRITE_DIFF_MAX_BYTES = 1024 * 1024;
const WRITE_DIFF_MAX_COMBINED_LINES = 20_000;
const WRITE_DIFF_MAX_EDIT_LENGTH = 2_000;

export function prepareFileWriteDiff(params: {
  path: string;
  content: string;
  beforeText?: string;
  created?: boolean;
}): FileDiff | undefined {
  const beforeText = params.created ? "" : params.beforeText;
  if (
    beforeText === undefined ||
    beforeText.includes("\uFFFD") ||
    beforeText.includes("\0") ||
    Buffer.byteLength(beforeText, "utf8") + Buffer.byteLength(params.content, "utf8") >
      WRITE_DIFF_MAX_BYTES ||
    countNewlines(beforeText) + countNewlines(params.content) > WRITE_DIFF_MAX_COMBINED_LINES
  ) {
    return undefined;
  }
  return prepareFileDiff(
    params.path,
    beforeText,
    params.content,
    params.created ? {} : { maxEditLength: WRITE_DIFF_MAX_EDIT_LENGTH },
  );
}

