const CORE_TOOL_BY_ID = new Map<string, CoreToolDefinition>(
  CORE_TOOL_DEFINITIONS.map((tool) => [tool.id, tool]),
);

// Runtime-only names have no configurable profile or catalog section.
const RUNTIME_ONLY_TOOL_FACTS = new Map<string, CoreToolFacts>([
  ...["search", "find", "grep", "glob", "tool_search", "tool_describe"].map(
    (name): [string, CoreToolFacts] => [name, { replay: "both" }],
  ),
  ["structured_output", { factoryFamily: "openclaw" }],
]);

export function resolveCoreToolFacts(toolId: string): Readonly<CoreToolFacts> | undefined {
  return CORE_TOOL_BY_ID.get(toolId) ?? RUNTIME_ONLY_TOOL_FACTS.get(toolId);
}

export type OpenClawCodingToolConstructionPlan = {
  includeBaseCodingTools: boolean;
  includeShellTools: boolean;
  includeChannelTools: boolean;
  includeOpenClawTools: boolean;
  includePluginTools: boolean;
};

const CORE_TOOL_FACTORY_DESCRIPTORS = [...CORE_TOOL_BY_ID, ...RUNTIME_ONLY_TOOL_FACTS].flatMap(
  ([name, { factoryFamily }]) => (factoryFamily ? [{ name, family: factoryFamily }] : []),
);

export function resolveCoreToolFactoryFamily(name: string): CoreToolFactoryFamily | undefined {
  return resolveCoreToolFacts(name)?.factoryFamily;
}

export function listCoreToolFactoryDescriptors(): readonly {
  name: string;
  family: CoreToolFactoryFamily;
}[] {
  return CORE_TOOL_FACTORY_DESCRIPTORS;
}

/** Coding primitives stay directly visible rather than requiring a tool-search round trip. */
export function isCoreCodingSurfaceToolName(name: string): boolean {
  const family = resolveCoreToolFactoryFamily(name);
  return family === "base-coding" || family === "shell";
}

// Keep Gateway declarations for 2026.9.8 until the next supervisor dialect.
export const CORE_WORKER_LAUNCH_TOOL_NAMES = Object.freeze(
  CORE_TOOL_DEFINITIONS.filter((tool) => tool.executionLocation).map((tool) => tool.id),
);

export function resolveCoreToolExecutionLocation(toolId: string): "placement" | "gateway" {
  return CORE_TOOL_BY_ID.get(toolId)?.executionLocation ?? "gateway";
}

// Section membership is static; capability filtering and response objects stay per request.
const CORE_TOOL_SECTIONS = CORE_TOOL_SECTION_ORDER.map(({ id, label }) => ({
  id,
  label,
  tools: CORE_TOOL_DEFINITIONS.filter((tool) => tool.sectionId === id),
}));

function listCoreToolIdsForProfile(profile: ToolProfileId): string[] {
  return CORE_TOOL_DEFINITIONS.filter((tool) => tool.profiles.includes(profile)).map(
    (tool) => tool.id,
  );
}

const CORE_TOOL_PROFILES: Record<ToolProfileId, ToolProfilePolicy> = {
  minimal: {
    allow: listCoreToolIdsForProfile("minimal"),
  },
  coding: {
    allow: [...listCoreToolIdsForProfile("coding"), "bundle-mcp"],
  },
  messaging: {
    allow: [...listCoreToolIdsForProfile("messaging"), "bundle-mcp"],
  },
  full: {
    allow: ["*"],
  },
};

function buildCoreToolGroupMap() {
  const sectionToolMap = new Map<string, string[]>();
  for (const tool of CORE_TOOL_DEFINITIONS) {
    if (tool.includeInSectionGroup === false) {
      continue;
    }
    const groupId = `group:${tool.sectionId}`;
    const list = sectionToolMap.get(groupId) ?? [];
    list.push(tool.id);
    sectionToolMap.set(groupId, list);
  }
  const openclawTools = CORE_TOOL_DEFINITIONS.filter((tool) => tool.includeInOpenClawGroup).map(
    (tool) => tool.id,
  );
  return {
    "group:openclaw": openclawTools,
    ...Object.fromEntries(sectionToolMap.entries()),
  };
}

/** Built-in core tool groups keyed by group id. */
export const CORE_TOOL_GROUPS = buildCoreToolGroupMap();

/** Profile options shown in model/tool configuration UIs. */
export const PROFILE_OPTIONS = [
  { id: "minimal", label: "Minimal" },
  { id: "coding", label: "Coding" },
  { id: "messaging", label: "Messaging" },
  { id: "full", label: "Full" },
] as const;

/** Resolves the allow/deny policy for a built-in tool profile. */
export function resolveCoreToolProfilePolicy(profile?: string): ToolProfilePolicy | undefined {
  if (!profile) {
    return undefined;
  }
  const resolved = CORE_TOOL_PROFILES[profile as ToolProfileId];
  if (!resolved?.allow && !resolved?.deny) {
    return undefined;
  }
  return {
    allow: resolved.allow ? [...resolved.allow] : undefined,
    deny: resolved.deny ? [...resolved.deny] : undefined,
  };
}

/** Lists configurable core tools; per-run authorization belongs to runtime assembly. */
export function listCoreToolSections(params?: {
  swarmEnabled?: boolean;
  personalInstructionsEnabled?: boolean;
}): CoreToolSection[] {
  // Callers resolve the swarm gate and pass the fact in; resolving config here
  // would couple this ui-shared module to the server graph.
  const swarmEnabled = params?.swarmEnabled === true;
  return CORE_TOOL_SECTIONS.map((section) => ({
    id: section.id,
    label: section.label,
    tools: section.tools
      .filter(
        (tool) =>
          (tool.id !== "agents_wait" || swarmEnabled) &&
          (tool.id !== "personal_instructions" || params?.personalInstructionsEnabled === true),
      )
      .map((tool) => ({
        id: tool.id,
        label: tool.id,
        description: tool.description,
      })),
  })).filter((section) => section.tools.length > 0);
}

/** Lists built-in profile ids that include a core tool. */
export function resolveCoreToolProfiles(toolId: string): ToolProfileId[] {
  return [...(CORE_TOOL_BY_ID.get(toolId)?.profiles ?? [])];
}

/** Returns true when a tool id is a known core tool. */
export function isKnownCoreToolId(toolId: string): boolean {
  return CORE_TOOL_BY_ID.has(toolId);
}

// Only host construction records trust; error names and prototypes are forgeable.
const trustedToolInputErrors = new WeakSet<object>();

export class ToolInputError extends Error {
  readonly status: number = 400;

  constructor(message: string) {
    super(message);
    this.name = "ToolInputError";
    trustedToolInputErrors.add(this);
  }
}

export class ToolAuthorizationError extends ToolInputError {
  override readonly status = 403;

  constructor(message: string) {
    super(message);
    this.name = "ToolAuthorizationError";
  }
}

export function isTrustedToolInputError(error: unknown): boolean {
  return typeof error === "object" && error !== null && trustedToolInputErrors.has(error);
}

import { PluginHostObject } from "../plugins/plugin-instance-owned-values.js";
import { resolveCoreToolFacts, TOOL_CALL_RAW_TOOL_NAME } from "./tool-catalog.js";
import { normalizeToolPolicyName } from "./tool-policy-shared.js";

type AgentToolReplaySafety = "bounded-read" | "dispatcher";

/** Private source-instance metadata survives only the host's canonical tool copies. */
class ToolReplaySafety extends PluginHostObject {
  #kind: AgentToolReplaySafety;

  constructor(tool: object, kind: AgentToolReplaySafety) {
    super(tool);
    this.#kind = kind;
  }

  static get(tool: object): AgentToolReplaySafety | undefined {
    return #kind in tool ? tool.#kind : undefined;
  }

  static set(tool: object, kind: AgentToolReplaySafety): void {
    if (#kind in tool) {
      tool.#kind = kind;
    } else {
      void new ToolReplaySafety(tool, kind);
    }
  }
}

export function bindAgentToolReplaySafety<T extends object>(
  tool: T,
  kind: AgentToolReplaySafety,
): T {
  ToolReplaySafety.set(tool, kind);
  return tool;
}

export function copyAgentToolReplaySafety(source: object, target: object): void {
  const kind = ToolReplaySafety.get(source);
  if (kind) {
    ToolReplaySafety.set(target, kind);
  }
}

type NamedTool = { name?: string };

function groupUniqueToolsByName(tools: NamedTool[]): Map<string, NamedTool | undefined> {
  const toolsByName = new Map<string, NamedTool | undefined>();
  for (const tool of tools) {
    const name = normalizeToolPolicyName(tool.name ?? "");
    if (!name) {
      continue;
    }
    toolsByName.set(name, toolsByName.has(name) ? undefined : tool);
  }
  return toolsByName;
}

/**
 * Tool names are not ownership boundaries. Callers must reject plugin/channel
 * instances before using this audited core-tool allowlist.
 */
export function isAgentToolReplaySafe(
  tool: { name?: string },
  options?: { declaredReplaySafe?: (tool: { name?: string }) => boolean | undefined },
): boolean {
  if (options?.declaredReplaySafe?.(tool) === false) {
    return false;
  }
  const safety = resolveCoreToolFacts(normalizeToolPolicyName(tool.name ?? ""))?.replay;
  return ToolReplaySafety.get(tool) === "bounded-read" || safety === "both" || safety === "blind";
}

/**
 * Classify one concrete tool instance for an explicitly restart-safe turn.
 * Unlike blind name-only replay, an owner declaration is sufficient because
 * the host filters the concrete registered instance before execution.
 */
export function isAgentToolRestartSafe(
  tool: { name?: string },
  options?: { declaredReplaySafe?: (tool: { name?: string }) => boolean | undefined },
): boolean {
  const declaredReplaySafe = options?.declaredReplaySafe?.(tool);
  if (declaredReplaySafe !== undefined) {
    return declaredReplaySafe;
  }
  // Tool Search can dispatch only into the catalog built after this filter.
  // Do not infer safety for other dispatchers or name-only interrupted calls.
  return (
    isAgentToolReplaySafe(tool) ||
    (tool.name === TOOL_CALL_RAW_TOOL_NAME && ToolReplaySafety.get(tool) === "dispatcher")
  );
}

/**
 * Name-only tool events are safe only when one concrete registered instance
 * owns the name. Duplicate/shadowed names fail closed.
 */
export function collectReplaySafeToolNames(
  tools: NamedTool[],
  options?: { declaredReplaySafe?: (tool: { name?: string }) => boolean | undefined },
): Set<string> {
  const replaySafeNames = new Set<string>();
  for (const [name, tool] of groupUniqueToolsByName(tools)) {
    if (tool && isAgentToolReplaySafe(tool, options)) {
      replaySafeNames.add(name);
    }
  }
  return replaySafeNames;
}

/** Bind name-only terminal events to the one concrete owner-declared side-effecting tool. */
export function collectSideEffectToolOwners(
  tools: NamedTool[],
  options: { declaredOwner: (tool: NamedTool) => string | undefined },
): Map<string, string> {
  const owners = new Map<string, string>();
  for (const [name, tool] of groupUniqueToolsByName(tools)) {
    const owner = tool ? options.declaredOwner(tool) : undefined;
    if (owner) {
      owners.set(name, owner);
    }
  }
  return owners;
}

// Destination descriptions stay runtime-free for schema and CLI imports.
// Runtime target mapping belongs to the action-spec owner.
/** Human-readable description for a single message-action destination. */
export const CHANNEL_TARGET_DESCRIPTION =
  "Recipient/channel: E.164 for WhatsApp/Signal, Telegram chat id/@username, Discord/Slack/Mattermost <channelId|user:ID|channel:ID>, or iMessage handle/chat_id";

/** Human-readable description for repeated message-action destinations. */
export const CHANNEL_TARGETS_DESCRIPTION =
  "Recipient/channel targets (same format as --target); accepts ids or names when the directory is available.";

type OwnedValueState<TInstance extends object> = {
  instance?: TInstance;
  originalInstance?: TInstance;
  original?: object;
};

export interface PluginValueInstances<TInstance extends object> {
  get(value: object): TInstance | undefined;
  set(value: object, instance: TInstance): this;
  adopt<T>(value: T, instance: TInstance): T;
  setHost(value: object, instance: TInstance): this;
  getOriginal(value: object, instance: TInstance): object | undefined;
  setOriginal(value: object, original: object, instance: TInstance): void;
}

// oxlint-disable-next-line typescript/no-extraneous-class -- Derived classes need a returning base constructor to stamp private fields on an existing object.
export class PluginHostObject {
  constructor(value: object) {
    // oxlint-disable-next-line eslint/no-constructor-return -- Derived private fields must be stamped on the host object without changing its prototype.
    return value;
  }
}

export class PluginFactoryBinding extends PluginHostObject {
  #factory: object;

  constructor(value: object, factory: object) {
    super(value);
    this.#factory = factory;
  }

  static belongsTo(value: object, factory: object): boolean {
    return #factory in value && value.#factory === factory;
  }
}

/** Installed once in the shared instance singleton, including its private-field brand. */
export function createPluginValueInstances<
  TInstance extends object,
>(): PluginValueInstances<TInstance> {
  // Private fields are installed on the returned object without invoking Proxy traps.
  // They cannot be discovered through reflection or forwarded by a foreign Proxy.
  class OwnedValue extends PluginHostObject {
    #state: OwnedValueState<TInstance>;

    constructor(value: object, state: OwnedValueState<TInstance>) {
      super(value);
      this.#state = state;
    }

    static get(value: unknown): OwnedValueState<TInstance> | undefined {
      if (value === null || (typeof value !== "object" && typeof value !== "function")) {
        return undefined;
      }
      return #state in value ? value.#state : undefined;
    }
  }

  const foreign = new WeakMap<object, TInstance>();
  const install = (value: object): OwnedValueState<TInstance> => {
    const current = OwnedValue.get(value);
    if (current) {
      return current;
    }
    const state: OwnedValueState<TInstance> = { instance: foreign.get(value) };
    if (state.instance) {
      foreign.delete(value);
    }
    void new OwnedValue(value, state);
    return state;
  };
  return {
    get(value: object): TInstance | undefined {
      return OwnedValue.get(value)?.instance ?? foreign.get(value);
    },
    set(value: object, instance: TInstance) {
      const owned = OwnedValue.get(value);
      if (owned) {
        owned.instance = instance;
      } else {
        foreign.set(value, instance);
      }
      return this;
    },
    adopt<T>(value: T, instance: TInstance): T {
      const seen = new Set<object>();
      const visit = (candidate: unknown) => {
        if (
          !candidate ||
          (typeof candidate !== "object" && typeof candidate !== "function") ||
          seen.has(candidate)
        ) {
          return;
        }
        seen.add(candidate);
        this.set(candidate, instance);
        for (const descriptor of Object.values(Object.getOwnPropertyDescriptors(candidate))) {
          if ("value" in descriptor) {
            visit(descriptor.value);
          }
        }
      };
      visit(value);
      return value;
    },
    setHost(value: object, instance: TInstance) {
      install(value).instance = instance;
      return this;
    },
    getOriginal(value: object, instance: TInstance): object | undefined {
      const owned = OwnedValue.get(value);
      return owned?.originalInstance === instance ? owned.original : undefined;
    },
    setOriginal(value: object, original: object, instance: TInstance): void {
      const owned = install(value);
      owned.originalInstance = instance;
      owned.original = original;
    },
  };
}

